from ta_moler.cmd.asimgr.genericasimgr import Genericasimgr


class GetHwInventoryInfo(Genericasimgr):
    """Gethwinventoryinfo command class."""

    def __init__(self, ne, connection, prompt=None, newline_chars=None, runner=None, pw=None,
                 options=None):
        """
        Gethwinventoryinfo command.

        :param ne: single IP address of one site.
        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        :param pw: sets of credentials for the sites.
        :param options: other options.
        """
        super(GetHwInventoryInfo, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                                 runner=runner)

        self.ne = ne
        self.pw = pw
        self.options = options

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"./getHwInventoryInfo.sh -ne {self.ne}"
        if self.pw:
            cmd = f"{cmd} -pw {self.pw}"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd


